import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Roadmaps — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"roadmaps-04-troubleshooting-and-faqs.md","filePath":"roadmaps-04-troubleshooting-and-faqs.md"}'),o={name:"roadmaps-04-troubleshooting-and-faqs.md"};function i(s,e,h,l,d,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="roadmaps-—-troubleshooting-faqs" tabindex="-1">Roadmaps — Troubleshooting &amp; FAQs <a class="header-anchor" href="#roadmaps-—-troubleshooting-faqs" aria-label="Permalink to &quot;Roadmaps — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common issues, edge cases, and answers to frequent questions</em></p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="who-can-create-a-roadmap" tabindex="-1">Who can create a Roadmap? <a class="header-anchor" href="#who-can-create-a-roadmap" aria-label="Permalink to &quot;Who can create a Roadmap?&quot;">​</a></h3><p>Any workspace member can create a Roadmap — it&#39;s not restricted to admins.</p><h3 id="can-i-have-more-than-one-roadmap" tabindex="-1">Can I have more than one Roadmap? <a class="header-anchor" href="#can-i-have-more-than-one-roadmap" aria-label="Permalink to &quot;Can I have more than one Roadmap?&quot;">​</a></h3><p>Yes. A workspace can have as many Roadmaps as you need. Common uses include separate roadmaps for different time horizons (annual vs quarterly), different audiences, or different product areas.</p><h3 id="can-the-same-feature-appear-in-multiple-roadmaps" tabindex="-1">Can the same Feature appear in multiple Roadmaps? <a class="header-anchor" href="#can-the-same-feature-appear-in-multiple-roadmaps" aria-label="Permalink to &quot;Can the same Feature appear in multiple Roadmaps?&quot;">​</a></h3><p>Yes. A Feature is a shared object — it can be added to as many Roadmaps as needed. Updates to the Feature (name, description, status) are reflected everywhere it appears.</p><h3 id="is-there-a-limit-to-how-many-levels-i-can-nest-in-the-sunburst" tabindex="-1">Is there a limit to how many levels I can nest in the sunburst? <a class="header-anchor" href="#is-there-a-limit-to-how-many-levels-i-can-nest-in-the-sunburst" aria-label="Permalink to &quot;Is there a limit to how many levels I can nest in the sunburst?&quot;">​</a></h3><p>No. You can nest as deeply as you need — the sunburst adds rings as you go. In practice, three levels is the most common structure; more than four can make the chart harder to read.</p><h3 id="can-i-reorder-items-within-the-same-hierarchy-level" tabindex="-1">Can I reorder items within the same hierarchy level? <a class="header-anchor" href="#can-i-reorder-items-within-the-same-hierarchy-level" aria-label="Permalink to &quot;Can I reorder items within the same hierarchy level?&quot;">​</a></h3><p>Yes. Drag items up or down within their level to reorder them. The sunburst updates in real time as you do.</p><h3 id="what-happens-to-my-features-if-i-archive-a-roadmap" tabindex="-1">What happens to my Features if I archive a Roadmap? <a class="header-anchor" href="#what-happens-to-my-features-if-i-archive-a-roadmap" aria-label="Permalink to &quot;What happens to my Features if I archive a Roadmap?&quot;">​</a></h3><p>Nothing — Features are unaffected by archiving. They remain in your Feature backlog exactly as before. Archiving only removes the Roadmap from your active list; it doesn&#39;t touch the Features within it.</p><h3 id="can-i-rename-a-roadmap-after-creating-it" tabindex="-1">Can I rename a Roadmap after creating it? <a class="header-anchor" href="#can-i-rename-a-roadmap-after-creating-it" aria-label="Permalink to &quot;Can I rename a Roadmap after creating it?&quot;">​</a></h3><p>Yes. Roadmap names can be edited at any time.</p><h3 id="what-s-the-difference-between-the-five-export-formats" tabindex="-1">What&#39;s the difference between the five export formats? <a class="header-anchor" href="#what-s-the-difference-between-the-five-export-formats" aria-label="Permalink to &quot;What&#39;s the difference between the five export formats?&quot;">​</a></h3><ul><li><strong>PNG single view</strong> — a static image of the sunburst, for embedding in emails or documents</li><li><strong>PPT single view</strong> — a single PowerPoint slide with the sunburst, for adding to an existing deck</li><li><strong>PPT full presentation</strong> — a complete deck with a slide for every item at every level, plus an Opportunity Canvas appendix</li><li><strong>Markdown (.md)</strong> — a text export of the full hierarchy, for pasting into Notion, Confluence, GitHub, or any Markdown-friendly tool</li><li><strong>HTML (shareable link)</strong> — a server-rendered, responsive snapshot published to a <code>/share/...</code> URL; no login required to view</li></ul><h3 id="does-the-full-ppt-export-include-every-level-of-the-hierarchy" tabindex="-1">Does the full PPT export include every level of the hierarchy? <a class="header-anchor" href="#does-the-full-ppt-export-include-every-level-of-the-hierarchy" aria-label="Permalink to &quot;Does the full PPT export include every level of the hierarchy?&quot;">​</a></h3><p>Yes. Every item at every level gets its own slide. The presentation walks through the sunburst step by step, deconstructing the plan from the center outward.</p><h3 id="can-i-add-ai-generated-content-to-my-export" tabindex="-1">Can I add AI-generated content to my export? <a class="header-anchor" href="#can-i-add-ai-generated-content-to-my-export" aria-label="Permalink to &quot;Can I add AI-generated content to my export?&quot;">​</a></h3><p>Yes. When exporting as a full PPT presentation, you can optionally enable AI-generated text descriptions per slide and AI-generated speaker notes tuned for internal general, internal executive, or external audiences. All generated content is fully editable in PowerPoint after export.</p><h3 id="why-aren-t-the-contextual-sizing-and-coloring-controls-active" tabindex="-1">Why aren&#39;t the contextual sizing and coloring controls active? <a class="header-anchor" href="#why-aren-t-the-contextual-sizing-and-coloring-controls-active" aria-label="Permalink to &quot;Why aren&#39;t the contextual sizing and coloring controls active?&quot;">​</a></h3><p>These controls only activate when Features in the Roadmap have Value and Effort scores entered in the Feature backlog. If the controls are greyed out, check that your Features have evaluation scores populated.</p><hr><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="my-sunburst-looks-flat-—-everything-is-in-one-ring" tabindex="-1">My sunburst looks flat — everything is in one ring <a class="header-anchor" href="#my-sunburst-looks-flat-—-everything-is-in-one-ring" aria-label="Permalink to &quot;My sunburst looks flat — everything is in one ring&quot;">​</a></h3><p>This means your items haven&#39;t been nested yet. Every item starts as a top-level entry until you drag it beneath a parent. To create hierarchy:</p><ol><li>Add your grouping items (Goals, Themes, etc.) first</li><li>Drag Feature items beneath them</li><li>The sunburst will add rings as you nest</li></ol><p>If drag-and-drop isn&#39;t working as expected, try dragging slowly and watching for the indent indicator before releasing.</p><h3 id="i-dragged-an-item-to-nest-it-but-it-moved-to-the-wrong-place" tabindex="-1">I dragged an item to nest it but it moved to the wrong place <a class="header-anchor" href="#i-dragged-an-item-to-nest-it-but-it-moved-to-the-wrong-place" aria-label="Permalink to &quot;I dragged an item to nest it but it moved to the wrong place&quot;">​</a></h3><p>Drag-and-drop nesting can take a moment to get used to. A few tips:</p><ul><li>Drag slowly — the target position highlights before you release</li><li>Watch for the indent indicator that shows where the item will land</li><li>If it goes to the wrong level, simply drag it again to reposition</li><li>Items can be reordered and renested as many times as needed</li></ul><h3 id="a-parent-item-disappeared-from-my-feature-backlog" tabindex="-1">A parent item disappeared from my Feature backlog <a class="header-anchor" href="#a-parent-item-disappeared-from-my-feature-backlog" aria-label="Permalink to &quot;A parent item disappeared from my Feature backlog&quot;">​</a></h3><p>This is expected behavior, not a bug. When an item has something nested beneath it, it becomes a grouping label and is removed from the backlog. It&#39;s now a tag on its children. If you want it back in the backlog, unnest all items beneath it.</p><h3 id="the-opportunity-canvas-appendix-is-missing-from-my-ppt-export" tabindex="-1">The Opportunity Canvas appendix is missing from my PPT export <a class="header-anchor" href="#the-opportunity-canvas-appendix-is-missing-from-my-ppt-export" aria-label="Permalink to &quot;The Opportunity Canvas appendix is missing from my PPT export&quot;">​</a></h3><p>Opportunity Canvases only appear in the appendix if they&#39;ve been generated for Features that are in the Roadmap. Check that:</p><ul><li>The Feature is included in the Roadmap</li><li>An Opportunity Canvas has been generated for that Feature on its Feature Detail page</li></ul><p>If both are true, try re-running the export.</p><h3 id="the-contextual-colors-aren-t-showing-on-parent-items-—-only-on-the-outer-ring" tabindex="-1">The contextual colors aren&#39;t showing on parent items — only on the outer ring <a class="header-anchor" href="#the-contextual-colors-aren-t-showing-on-parent-items-—-only-on-the-outer-ring" aria-label="Permalink to &quot;The contextual colors aren&#39;t showing on parent items — only on the outer ring&quot;">​</a></h3><p>This is correct behavior. Contextual coloring only applies to the outermost ring (Features). Parent and grandparent items retain their hierarchy color families. This is intentional — mixing contextual colors into the hierarchy would make the chart harder to read.</p><h3 id="my-ai-generated-speaker-notes-don-t-match-the-audience-i-selected" tabindex="-1">My AI-generated speaker notes don&#39;t match the audience I selected <a class="header-anchor" href="#my-ai-generated-speaker-notes-don-t-match-the-audience-i-selected" aria-label="Permalink to &quot;My AI-generated speaker notes don&#39;t match the audience I selected&quot;">​</a></h3><p>Double-check the audience setting in the export options before generating. If the notes were generated with the wrong audience, re-export with the correct setting selected. All content is editable in PowerPoint, so you can also adjust the tone manually after export.</p><hr><p><em>This is version 1 of the Roadmaps documentation, based on the Lodestone knowledge base from early 2025, updated with confirmed platform behavior.</em></p>',47)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
